int PackBrowser::PackList::getNumRows(){return (int)owner.library.packs.size()+2;}

void PackBrowser::PackList::paintListBoxItem(int row,Graphics& g,int width,int height,bool selected){g.fillAll(selected?nd::colour(Colour(0xff304b63)):bg);String title=row==0?"All entries":row==1?"Favorites":owner.library.packs[(size_t)row-2].name;g.setFont(FontOptions(12.f));g.setColour(nd::colour(selected?blue:white));g.drawText(title,8,0,width-16,height,Justification::centredLeft,true);if(row==owner.dropRow){g.setColour(nd::colour(blue));g.drawRect(1,1,width-2,height-2,2);}}

void PackBrowser::PackList::selectedRowsChanged(int row){owner.selectPack(row);}

PackBrowser::PackDropList::PackDropList(PackBrowser& browser,ListBoxModel* model):ListBox("Packs",model),owner(browser){}
bool PackBrowser::PackDropList::isInterestedInDragSource(const SourceDetails& source){auto description=source.description;return description.getProperty("kind",{}).toString()=="NoCTRL.Preset"&&description.getProperty("instance",{}).toString()==String::toHexString((int64)(intptr_t)&owner)&&owner.library.canManagePreset(description.getProperty("preset",{}).toString());}
void PackBrowser::PackDropList::itemDragEnter(const SourceDetails& source){itemDragMove(source);}
void PackBrowser::PackDropList::itemDragMove(const SourceDetails& source){owner.dropRow=isInterestedInDragSource(source)?owner.dropDestination(source):-1;repaint();}
void PackBrowser::PackDropList::itemDragExit(const SourceDetails&){owner.dropRow=-1;repaint();}
void PackBrowser::PackDropList::itemDropped(const SourceDetails& source){int row=isInterestedInDragSource(source)?owner.dropDestination(source):-1;owner.dropRow=-1;repaint();if(row<2)return;auto packId=owner.library.packs[(size_t)row-2].id;owner.moveSelectedTo(source.description.getProperty("preset",{}).toString(),packId);}
int PackBrowser::dropDestination(const DragAndDropTarget::SourceDetails& source)const{int row=packList.getRowContainingPosition(source.localPosition.x,source.localPosition.y);if(row<2||row-2>=(int)library.packs.size())return -1;return library.canMovePreset(source.description.getProperty("preset",{}).toString(),library.packs[(size_t)row-2].id)?row:-1;}
var PackBrowser::getDragSourceDescription(const SparseSet<int>& rows){if(saving||rows.isEmpty())return {};int row=rows[0];if(row<0||row>=(int)visibleRows.size())return {};auto& entry=library.presets[visibleRows[(size_t)row]];if(!library.canManagePreset(entry.id))return {};auto object=std::make_unique<DynamicObject>();object->setProperty("kind","NoCTRL.Preset");object->setProperty("instance",String::toHexString((int64)(intptr_t)this));object->setProperty("preset",entry.id);return var(object.release());}
void PackBrowser::deleteKeyPressed(int row){if(row>=0){selectRow(row);deleteSelected();}}
void PackBrowser::cellClicked(int row,int,const MouseEvent& event){if(event.mods.isPopupMenu())presetMenu(row);}
void PackBrowser::presetMenu(int row){if(row<0||row>=(int)visibleRows.size())return;table.selectRow(row);selectRow(row);auto* entry=selected();if(!entry)return;auto id=entry->id;PopupMenu menu,moves;StringArray targets;for(auto& pack:library.packs)if(library.canMovePreset(id,pack.id)){targets.add(pack.id);moves.addItem(100+targets.size(),pack.name);}menu.addSubMenu(String::fromUTF8("Move to another pack"),moves,targets.size()>0);menu.addItem(2,"Rename...",library.canManagePreset(id));menu.addItem(1,String::fromUTF8("Delete preset"),library.canManagePreset(id));menu.addItem(3,"Import Info");auto safe=Component::SafePointer<PackBrowser>(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&table),[safe,id,targets](int choice){if(!safe)return;if(choice==1){safe->selectedId=id;safe->deleteSelected();}else if(choice==2){safe->selectedId=id;safe->renameEntryButton.onClick();}else if(choice==3){if(safe->onInfoRequested)safe->onInfoRequested();}else if(choice>=101&&choice-101<targets.size())safe->moveSelectedTo(id,targets[choice-101]);});}
void PackBrowser::deleteSelected(){auto* pointer=selected();if(!pointer||saving)return;auto entry=*pointer;bool loaded=PresetLibrary::currentPresetFile(processor)==entry.file;auto assets=std::atomic_load(&processor.importedAssets);loaded|=assets&&assets->sourcePath==entry.file.getFullPathName();auto result=library.deletePreset(entry.id);if(result.failed()){setStatus(result.getErrorMessage(),true);return;}if(loaded)processor.state.state.setProperty("currentPresetFile",entry.file.getFullPathName(),nullptr);selectedId.clear();table.deselectAllRows();deleteButton.setEnabled(false);commitButton.setEnabled(false);loadButton.setEnabled(false);previewButton.setEnabled(false);fillDetails({});refresh();setStatus(String::fromUTF8("Deleted: ")+entry.metadata.name+String::fromUTF8(" / moved to the Recycle Bin. The loaded sound is preserved."));if(onLibraryChanged)onLibraryChanged();}
void PackBrowser::moveSelectedTo(const String& id,const String& packId,String newName){LibraryPreset entry;bool found=false;for(auto& candidate:library.presets)if(candidate.id==id){entry=candidate;found=true;break;}if(!found)return;bool loaded=PresetLibrary::currentPresetFile(processor)==entry.file;auto assets=std::atomic_load(&processor.importedAssets);loaded|=assets&&assets->sourcePath==entry.file.getFullPathName();File moved;auto result=library.movePreset(id,packId,moved,newName);if(result.failed()){setStatus(result.getErrorMessage(),true);return;}if(loaded){processor.state.state.setProperty("currentPresetFile",moved.getFullPathName(),nullptr);for(auto& candidate:library.presets)if(candidate.file==moved){processor.state.state.setProperty("userPresetName",candidate.metadata.name,nullptr);processor.state.state.setProperty("libraryMetadata",JSON::toString(candidate.metadata.toJson(),true),nullptr);break;}}packFilter=packId;selectedId=moved.getFullPathName();search.clear();categoryFilter.setSelectedId(1,dontSendNotification);refresh();for(int i=0;i<(int)library.packs.size();++i)if(library.packs[(size_t)i].id==packId)packList.selectRow(i+2);selectedId=moved.getFullPathName();for(int row=0;row<(int)visibleRows.size();++row)if(library.presets[visibleRows[(size_t)row]].file==moved){table.selectRow(row);selectRow(row);break;}setStatus(String::fromUTF8("Moved: ")+moved.getFileName()+(entry.file.hasFileExtension("SerumPreset")?" / NoCTRL preset with embedded assets":""));if(onLibraryChanged)onLibraryChanged();}

