PackBrowser::~PackBrowser(){for(auto& dialog:dialogs)if(dialog)delete dialog.getComponent();setLookAndFeel(nullptr);table.setModel(nullptr);packList.setModel(nullptr);}

void PackBrowser::rebuildDestinations(String preferred){String previous=preferred.isNotEmpty()?preferred:destination.getText();destination.clear(dontSendNotification);int index=1;for(auto& pack:library.packs)if(saving?pack.writable:!pack.factory){destination.addItem(pack.name,index++);if(pack.name==previous||pack.id==previous)destination.setSelectedId(index-1,dontSendNotification);}if(destination.getSelectedId()==0&&destination.getNumItems())destination.setSelectedItemIndex(0,dontSendNotification);}

void PackBrowser::refresh(){String previous=selectedId;library.refresh();auto previousCategory=categoryFilter.getSelectedId()>1?categoryFilter.getText():String();auto chosenCategory=category.getSelectedId()>1?category.getText():String();categoryFilter.clear(dontSendNotification);category.clear(dontSendNotification);categoryFilter.addItem("All categories",1);category.addItem("No category",1);categoryFilter.addItemList(library.categories,2);category.addItemList(library.categories,2);categoryFilter.setSelectedId(jmax(1,library.categories.indexOf(previousCategory)+2),dontSendNotification);category.setSelectedId(jmax(1,library.categories.indexOf(chosenCategory)+2),dontSendNotification);if(packFilter!="all"&&packFilter!="favorites"&&!library.findPack(packFilter))packFilter="all";rebuildDestinations();removePackButton.setEnabled(library.findPack(packFilter)&&!library.findPack(packFilter)->factory);renamePackButton.setEnabled(removePackButton.isEnabled());packList.updateContent();filterRows();for(int i=0;i<(int)visibleRows.size();++i)if(library.presets[visibleRows[(size_t)i]].id==previous){table.selectRow(i);selectRow(i);break;}repaint();}

int PackBrowser::getNumRows(){return (int)visibleRows.size();}

void PackBrowser::filterRows(){deleteButton.setEnabled(false);renameEntryButton.setEnabled(false);moveButton.setEnabled(false);String query=search.getText().trim(),categoryName=categoryFilter.getSelectedId()>1?categoryFilter.getText():String();visibleRows.clear();for(size_t i=0;i<library.presets.size();++i){auto& entry=library.presets[i];if(packFilter=="favorites"&&entry.metadata.rating<4)continue;if(packFilter!="all"&&packFilter!="favorites"&&entry.packId!=packFilter)continue;if(categoryName.isNotEmpty()&&!entry.metadata.category.equalsIgnoreCase(categoryName))continue;String text=entry.metadata.name+" "+entry.metadata.author+" "+entry.metadata.category+" "+entry.metadata.tags+" "+entry.metadata.description+" "+entry.metadata.notes+" "+entry.packName;if(query.isNotEmpty()&&!text.containsIgnoreCase(query))continue;visibleRows.push_back(i);}sortOrderChanged(sortColumn,ascending);table.updateContent();table.repaint();repaint();}

void PackBrowser::sortOrderChanged(int column,bool forwards){sortColumn=column;ascending=forwards;std::stable_sort(visibleRows.begin(),visibleRows.end(),[&](size_t a,size_t b){auto& x=library.presets[a];auto& y=library.presets[b];int result=0;if(column==4)result=x.modified<y.modified?-1:x.modified>y.modified?1:0;else if(column==5)result=x.metadata.rating-y.metadata.rating;else{String u=column==2?x.metadata.category:column==3?x.metadata.author:x.metadata.name,v=column==2?y.metadata.category:column==3?y.metadata.author:y.metadata.name;result=u.compareIgnoreCase(v);}if(result==0)result=x.metadata.name.compareIgnoreCase(y.metadata.name);return forwards?result<0:result>0;});table.repaint();}

void PackBrowser::selectPack(int row){if(row<0)return;packFilter=row==0?"all":row==1?"favorites":row-2<(int)library.packs.size()?library.packs[(size_t)row-2].id:"all";removePackButton.setEnabled(library.findPack(packFilter)&&!library.findPack(packFilter)->factory);renamePackButton.setEnabled(removePackButton.isEnabled());table.deselectAllRows();selectedId.clear();saving=false;setDetailsEnabled(false);fillDetails({});commitButton.setEnabled(false);loadButton.setEnabled(false);previewButton.setEnabled(false);deleteButton.setEnabled(false);filterRows();if(auto* pack=library.findPack(packFilter))if(pack->writable)rebuildDestinations(pack->id);}

const LibraryPreset* PackBrowser::selected()const{for(auto& entry:library.presets)if(entry.id==selectedId)return &entry;return nullptr;}

void PackBrowser::selectedRowsChanged(int row){selectRow(row);}

void PackBrowser::selectRow(int row){if(row<0||row>=(int)visibleRows.size())return;auto& entry=library.presets[visibleRows[(size_t)row]];selectedId=entry.id;deleteButton.setEnabled(library.canManagePreset(entry.id));renameEntryButton.setEnabled(deleteButton.isEnabled());moveButton.setEnabled(deleteButton.isEnabled());setDetailsEnabled(true);saving=false;fillDetails(entry.metadata);rebuildDestinations(entry.packId);commitButton.setButtonText("SAVE DETAILS");commitButton.setEnabled(true);loadButton.setEnabled(true);previewButton.setEnabled(true);setStatus(entry.packName+" / "+(entry.program>=0?"Built-in preset":entry.writable?"Your NoCTRL preset":entry.file.hasFileExtension("ncsynth")?"Factory NoCTRL preset":"Imported Serum preset"));}

void PackBrowser::fillDetails(const PresetMetadata& m){name.setText(m.name,false);author.setText(m.author,false);category.setSelectedId(m.category.isEmpty()?1:jmax(1,library.categories.indexOf(m.category)+2),dontSendNotification);description.setText(m.description,false);notes.setText(m.notes,false);tags.setText(m.tags,false);rating=m.rating;updateStars();}

PresetMetadata PackBrowser::details()const{PresetMetadata m;m.name=name.getText().trim();m.author=author.getText().trim();m.category=category.getSelectedId()>1?category.getText().trim():String();m.description=description.getText();m.notes=notes.getText();m.tags=tags.getText();m.rating=rating;return m;}

void PackBrowser::updateStars(){for(int i=0;i<5;++i)stars[(size_t)i].setToggleState(i<rating,dontSendNotification);}

void PackBrowser::paintRowBackground(Graphics& g,int row,int width,int height,bool selected){g.fillAll(selected?nd::colour(Colour(0xff304b63)):row%2?nd::colour(Colour(0xff1b2b36)):bg);g.setColour(nd::colour(line.withAlpha(.5f)));g.drawHorizontalLine(height-1,0,(float)width);}

void PackBrowser::paintCell(Graphics& g,int row,int column,int width,int height,bool selected){if(row<0||row>=(int)visibleRows.size())return;auto& entry=library.presets[visibleRows[(size_t)row]];if(column==5){for(int i=0;i<5;++i){Path star;star.addStar({10.f+i*14, height*.5f},5,2.2f,5.f);g.setColour(nd::colour(i<entry.metadata.rating?blue:line));g.fillPath(star);}return;}String value=column==1?entry.metadata.name:column==2?entry.metadata.category:column==3?entry.metadata.author:entry.modified.toMilliseconds()>0?entry.modified.formatted("%Y-%m-%d"):"Factory";label(g,value,{9,0,width-17,height},column==1?12.f:10.f,selected?blue:column==1?white:grey);}

void PackBrowser::cellDoubleClicked(int row,int,const MouseEvent&){selectRow(row);loadSelected();}

void PackBrowser::returnKeyPressed(int row){selectRow(row);loadSelected();}

void PackBrowser::loadSelected(){auto* pointer=selected();if(!pointer)return;auto entry=*pointer;String error;if(entry.program>=0)processor.loadPreset(entry.program);else if(entry.file.hasFileExtension("SerumPreset")){if(!processor.loadSerumPreset(entry.file,entry.file.getParentDirectory(),error)){setStatus(error,true);return;}}else{MemoryBlock bytes;if(!entry.file.loadFileAsData(bytes)||bytes.getSize()>256*1024*1024){setStatus("Could not read preset.",true);return;}auto xml=AudioProcessor::getXmlFromBinary(bytes.getData(),(int)bytes.getSize());if(!xml||!noctrl::isSynthState(*xml)){setStatus("This is not a valid NoCTRL preset.",true);return;}processor.loadSoundState(bytes.getData(),(int)bytes.getSize());processor.state.state.setProperty("currentPresetFile",entry.file.getFullPathName(),nullptr);}processor.state.state.setProperty("currentPresetFile",entry.file.getFullPathName(),nullptr);processor.state.state.setProperty("userPresetName",entry.metadata.name,nullptr);processor.state.state.setProperty("libraryMetadata",JSON::toString(entry.metadata.toJson(),true),nullptr);setStatus("Loaded: "+entry.metadata.name);}

void PackBrowser::showSaveCurrent(){setDetailsEnabled(true);renameEntryButton.setEnabled(false);moveButton.setEnabled(false);deleteButton.setEnabled(false);table.deselectAllRows();saving=true;selectedId.clear();if(destination.getNumItems()==0){String id;auto result=library.createPack("My Presets","NoCTRL","My own sounds",id);if(result.failed()){setStatus(result.getErrorMessage(),true);return;}refresh();rebuildDestinations(id);if(onLibraryChanged)onLibraryChanged();}PresetMetadata metadata;auto json=JSON::parse(processor.state.state.getProperty("libraryMetadata").toString());if(json.isObject())metadata=PresetMetadata::fromJson(json);else if(auto imported=std::atomic_load(&processor.importedAssets)){metadata.name=imported->name;metadata.category=PresetLibrary::inferCategory(metadata.name);}else metadata.name=processor.getProgramName(processor.currentPreset);if(metadata.author.isEmpty())metadata.author="NoCTRL";fillDetails(metadata);saving=true;setDetailsEnabled(true);rebuildDestinations();commitButton.setButtonText("SAVE NEW PRESET");commitButton.setEnabled(true);loadButton.setEnabled(false);previewButton.setEnabled(false);setStatus("SAVE CURRENT SOUND / Choose a pack and name, then Save to Pack. Existing files are kept.");name.grabKeyboardFocus();name.selectAll();}

Result PackBrowser::overwriteCurrent(){if(!PresetLibrary::canOverwriteCurrent(processor))return Result::fail("Please save a new user preset first.");auto file=PresetLibrary::currentPresetFile(processor);PresetMetadata metadata=PresetMetadata::fromJson(JSON::parse(processor.state.state.getProperty("libraryMetadata").toString()));if(metadata.name.isEmpty())metadata.name=processor.state.state.getProperty("userPresetName",file.getFileNameWithoutExtension()).toString();MemoryBlock bytes;processor.getStateInformation(bytes);auto result=library.overwritePreset(file,metadata,bytes);if(result.failed())return result;processor.state.state.setProperty("userPresetName",metadata.name,nullptr);processor.state.state.setProperty("libraryMetadata",JSON::toString(metadata.toJson(),true),nullptr);refresh();setStatus(juce::String::fromUTF8("Preset overwritten: ")+file.getFileName());if(onLibraryChanged)onLibraryChanged();return Result::ok();}

void PackBrowser::setDetailsEnabled(bool enabled){for(auto* editor:{&name,&author,&description,&notes,&tags})editor->setEnabled(enabled);category.setEnabled(enabled);for(auto& star:stars)star.setEnabled(enabled);}
void PackBrowser::promptName(String title,String initial,std::function<void(String)> action){auto* dialog=new AlertWindow(title,"Name",MessageBoxIconType::NoIcon,this);dialogs.add(dialog);dialog->addTextEditor("name",initial);dialog->addButton("OK",1,KeyPress(KeyPress::returnKey));dialog->addButton("CANCEL",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<PackBrowser>(this);dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,action](int result){if(safe&&result==1)action(dialog->getTextEditorContents("name"));}),true);}
void PackBrowser::quickMetadata(String nextCategory,int nextRating){auto* pointer=selected();if(!pointer||saving)return;auto entry=*pointer;auto draft=details();auto metadata=entry.metadata;metadata.category=nextCategory;metadata.rating=nextRating;bool loaded=PresetLibrary::currentPresetFile(processor)==entry.file;auto result=library.updateMetadata(entry,metadata);if(result.failed()){setStatus(result.getErrorMessage(),true);return;}if(loaded)processor.state.state.setProperty("libraryMetadata",JSON::toString(metadata.toJson(),true),nullptr);refresh();if(onLibraryChanged)onLibraryChanged();name.setText(draft.name,false);author.setText(draft.author,false);description.setText(draft.description,false);notes.setText(draft.notes,false);tags.setText(draft.tags,false);setStatus("Rating / category saved");}
void PackBrowser::categoryMenu(){PopupMenu menu,rename,remove;menu.addItem(1,"Add category...");auto categories=library.categories;for(int i=0;i<categories.size();++i){rename.addItem(100+i,categories[i]);remove.addItem(1000+i,categories[i]);}menu.addSubMenu("Rename category",rename,categories.size()>0);menu.addSubMenu("Remove category",remove,categories.size()>0);auto safe=Component::SafePointer<PackBrowser>(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&categoryButton),[safe,categories](int choice){if(!safe)return;auto apply=[safe](String oldName,String newName){if(!safe)return;auto result=safe->library.editCategory(oldName,newName);safe->refresh();safe->setStatus(result.wasOk()?"Categories saved":result.getErrorMessage(),result.failed());if(result.wasOk()){auto active=PresetLibrary::currentPresetFile(safe->processor);for(auto& entry:safe->library.presets)if(entry.file==active){safe->processor.state.state.setProperty("libraryMetadata",JSON::toString(entry.metadata.toJson(),true),nullptr);break;}}if(result.wasOk()&&safe->onLibraryChanged)safe->onLibraryChanged();};if(choice==1)safe->promptName("New category","",[apply](String name){apply({},name);});else if(choice>=1000&&choice-1000<categories.size())apply(categories[choice-1000],{});else if(choice>=100&&choice-100<categories.size()){auto old=categories[choice-100];safe->promptName("Rename category",old,[apply,old](String name){apply(old,name);});}});}
void PackBrowser::packActions(){auto* pointer=library.findPack(packFilter);if(!pointer||pointer->factory)return;auto pack=*pointer;PopupMenu menu;menu.addItem(1,"Rename folder...");menu.addItem(2,String::fromUTF8("Delete folder..."));auto safe=Component::SafePointer<PackBrowser>(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&renamePackButton),[safe,pack](int choice){if(!safe)return;if(choice==2)safe->removePack();else if(choice==1)safe->promptName("Rename folder",pack.name,[safe,pack](String name){if(!safe)return;auto active=PresetLibrary::currentPresetFile(safe->processor);File selectedFile;for(auto& entry:safe->library.presets)if(entry.id==safe->selectedId)selectedFile=entry.file;String next;auto result=safe->library.renamePack(pack.id,name,next);if(result.failed()){safe->setStatus(result.getErrorMessage(),true);return;}File folder(next);if(active.isAChildOf(pack.folder))safe->processor.state.state.setProperty("currentPresetFile",folder.getChildFile(active.getRelativePathFrom(pack.folder)).getFullPathName(),nullptr);if(selectedFile.isAChildOf(pack.folder))safe->selectedId=folder.getChildFile(selectedFile.getRelativePathFrom(pack.folder)).getFullPathName();auto previous=std::atomic_load(&safe->processor.importedAssets);if(previous&&File::isAbsolutePath(previous->sourcePath)&&File(previous->sourcePath).isAChildOf(pack.folder)){auto assets=std::make_shared<ImportedAssets>(*previous);assets->sourcePath=folder.getChildFile(File(previous->sourcePath).getRelativePathFrom(pack.folder)).getFullPathName();std::atomic_store(&safe->processor.importedAssets,std::shared_ptr<const ImportedAssets>(assets));}safe->packFilter=next;safe->refresh();safe->setStatus("Folder renamed");if(safe->onLibraryChanged)safe->onLibraryChanged();});});}

void PackBrowser::newPack(){auto* dialog=new AlertWindow("Create your own pack","Pack name and author are saved with your library.",MessageBoxIconType::NoIcon,this);dialog->addTextEditor("packName","","PACK NAME");dialog->addTextEditor("author","NoCTRL","AUTHOR");dialog->addTextEditor("description","","DESCRIPTION");dialog->addButton("CREATE PACK",1,KeyPress(KeyPress::returnKey));dialog->addButton("CANCEL",0,KeyPress(KeyPress::escapeKey));auto safe=Component::SafePointer<PackBrowser>(this);dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog](int result){if(!safe||result!=1)return;String id;auto created=safe->library.createPack(dialog->getTextEditorContents("packName"),dialog->getTextEditorContents("author"),dialog->getTextEditorContents("description"),id);if(created.failed()){safe->setStatus(created.getErrorMessage(),true);return;}safe->refresh();safe->rebuildDestinations(id);for(int i=0;i<(int)safe->library.packs.size();++i)if(safe->library.packs[(size_t)i].id==id)safe->packList.selectRow(i+2);safe->setStatus("Created pack: "+dialog->getTextEditorContents("packName"));if(safe->onLibraryChanged)safe->onLibraryChanged();}),true);}

void PackBrowser::removePack(){auto* pack=library.findPack(packFilter);if(!pack||pack->factory)return;auto id=pack->id;auto title=pack->name;auto safe=Component::SafePointer<PackBrowser>(this);AlertWindow::showOkCancelBox(MessageBoxIconType::WarningIcon,"Remove pack?","Move \""+title+"\" and all its presets to the Recycle Bin?\n\nThe currently loaded sound stays available. You can restore the pack from the Recycle Bin.","REMOVE PACK","CANCEL",this,ModalCallbackFunction::create([safe,id,title](int result){if(!safe||result!=1)return;auto removed=safe->library.removePack(id);if(removed.failed()){safe->setStatus(removed.getErrorMessage(),true);return;}safe->packFilter="all";safe->selectedId.clear();safe->saving=false;safe->table.deselectAllRows();safe->commitButton.setEnabled(false);safe->loadButton.setEnabled(false);safe->previewButton.setEnabled(false);safe->fillDetails({});safe->refresh();safe->packList.selectRow(0);safe->setStatus("Removed: "+title+" / moved to the Recycle Bin.");if(safe->onLibraryChanged)safe->onLibraryChanged();}));}

void PackBrowser::commit(){auto metadata=details();if(saving){String target=destination.getText();const LibraryPack* pack=nullptr;for(auto& candidate:library.packs)if(candidate.writable&&candidate.name==target){pack=&candidate;break;}if(!pack){setStatus("Choose one of your own packs first.",true);return;}MemoryBlock bytes;processor.getStateInformation(bytes);File saved;auto result=library.savePreset(pack->id,metadata,bytes,saved);if(result.failed()){setStatus(result.getErrorMessage(),true);return;}selectedId=saved.getFullPathName();processor.state.state.setProperty("currentPresetFile",saved.getFullPathName(),nullptr);processor.state.state.removeProperty("factoryPreset",nullptr);processor.state.state.setProperty("userPresetName",saved.getFileNameWithoutExtension(),nullptr);metadata.name=saved.getFileNameWithoutExtension();processor.state.state.setProperty("libraryMetadata",JSON::toString(metadata.toJson(),true),nullptr);saving=false;packFilter="all";search.clear();categoryFilter.setSelectedId(1,dontSendNotification);refresh();setStatus("Saved: "+saved.getFileName()+" / samples and wavetables are embedded.");if(onLibraryChanged)onLibraryChanged();}else if(auto* current=selected()){auto entry=*current;bool loaded=PresetLibrary::currentPresetFile(processor)==entry.file;File target=entry.file;if(metadata.name!=entry.metadata.name){auto renamed=library.movePreset(entry.id,entry.packId,target,metadata.name);if(renamed.failed()){setStatus(renamed.getErrorMessage(),true);return;}for(auto& candidate:library.presets)if(candidate.file==target){entry=candidate;metadata.name=candidate.metadata.name;break;}selectedId=target.getFullPathName();}auto result=library.updateMetadata(entry,metadata);if(result.failed()){setStatus(result.getErrorMessage(),true);return;}if(loaded){processor.state.state.setProperty("currentPresetFile",target.getFullPathName(),nullptr);processor.state.state.setProperty("userPresetName",metadata.name,nullptr);processor.state.state.setProperty("libraryMetadata",JSON::toString(metadata.toJson(),true),nullptr);}refresh();setStatus("Details saved.");if(onLibraryChanged)onLibraryChanged();}}

void PackBrowser::setStatus(String text,bool error){status=std::move(text);setColour(Label::textColourId,error?nd::colour(Colour(0xffff997b)):grey);repaint();}

void PackBrowser::paintOverChildren(Graphics& g){nd::Scope suitScope("library");libraryCorners(g);}
void PackBrowser::paint(Graphics& g){nd::Scope suitScope("library");libraryChrome(g,"PRESET LIBRARY",String(library.packs.size())+" folders / "+String(library.presets.size())+" entries",saving?"NEW PRESET":"DETAILS");UiStyle::plot(g,{232,426,645,180});if(auto* entry=selected()){libraryText(g,entry->metadata.name,{248,442,610,28},16,blue);libraryText(g,entry->metadata.author,{248,475,610,22},12);g.setColour(nd::colour(white));g.setFont(FontOptions(12.f));g.drawFittedText(entry->metadata.description,{248,504,610,56},Justification::topLeft,3);libraryText(g,"Double-click to load / PREVIEW: MIDI clip",{248,575,350,20},10);}else libraryText(g,"Select an entry or drag it into another folder",{248,475,610,40},12);libraryText(g,status,{232,650,645,25},10,findColour(Label::textColourId));if(visibleRows.empty())libraryText(g,"No matching entries. Choose another folder or filter.",{245,220,610,60},13);}

